-- Reviewed opening state and journal for prior unpaid interest. No historical income is reposted.
CREATE TABLE loan_billing_opening_states (
 loan_id TEXT PRIMARY KEY REFERENCES loans(id), opening_journal_id TEXT NOT NULL UNIQUE,
 rate_basis_points INTEGER NOT NULL, period_days INTEGER NOT NULL,
 interest_due_minor INTEGER NOT NULL CHECK(interest_due_minor>=0), recognized_interest_minor INTEGER NOT NULL CHECK(recognized_interest_minor>=interest_due_minor),
 minimum_assessed INTEGER NOT NULL CHECK(minimum_assessed IN (0,1)), interest_receivable_account_id TEXT NOT NULL REFERENCES ledger_accounts(id),
 clearing_account_id TEXT NOT NULL REFERENCES ledger_accounts(id), interest_journal_id TEXT UNIQUE, source TEXT NOT NULL CHECK(length(trim(source))>0),
 request_key TEXT NOT NULL UNIQUE, created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CHECK((interest_due_minor=0 AND interest_journal_id IS NULL) OR (interest_due_minor>0 AND interest_journal_id IS NOT NULL)),
 CHECK((rate_basis_points=200 AND period_days IN (30,60)) OR (rate_basis_points=500 AND period_days=180))
);
CREATE TABLE loan_billing_opening_state_corrections (
 id TEXT PRIMARY KEY, loan_id TEXT NOT NULL REFERENCES loans(id), opening_request_key TEXT NOT NULL UNIQUE,
 original_details TEXT NOT NULL, reversal_journal_id TEXT UNIQUE, reason TEXT NOT NULL CHECK(length(trim(reason))>0),
 request_key TEXT NOT NULL UNIQUE, period_open_confirmed INTEGER NOT NULL CHECK(period_open_confirmed=1),
 created_by TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','final')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
-- The reviewed opening already includes all transactions through its cutoff.
-- Recording another historical repayment after that review would invalidate it.
CREATE TRIGGER billing_opening_cutoff_repayment_insert BEFORE INSERT ON loan_repayments
WHEN EXISTS(SELECT 1 FROM loan_openings o WHERE o.loan_id=NEW.loan_id AND NEW.payment_date<=o.opening_date)
BEGIN SELECT RAISE(ABORT,'repayment must follow the reviewed opening cutoff'); END;
CREATE TRIGGER billing_opening_cutoff_repayment_update BEFORE UPDATE OF loan_id,payment_date ON loan_repayments
WHEN EXISTS(SELECT 1 FROM loan_openings o WHERE o.loan_id=NEW.loan_id AND NEW.payment_date<=o.opening_date)
BEGIN SELECT RAISE(ABORT,'repayment must follow the reviewed opening cutoff'); END;
CREATE TRIGGER opening_legacy_repayment_post_guard BEFORE UPDATE OF status ON journal_entries
WHEN NEW.status='posted' AND NEW.source_type='loan-repayment' AND EXISTS(SELECT 1 FROM loan_repayments r JOIN loan_openings o ON o.loan_id=r.loan_id WHERE r.id=NEW.source_id)
BEGIN SELECT RAISE(ABORT,'brought-forward loan repayment requires billing setup'); END;
CREATE TRIGGER billing_opening_state_insert BEFORE INSERT ON loan_billing_opening_states BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.created_by AND role='admin') OR EXISTS(SELECT 1 FROM loan_billing_configs WHERE loan_id=NEW.loan_id) OR EXISTS(SELECT 1 FROM loan_billing_opening_state_corrections WHERE opening_request_key=NEW.request_key) OR NOT EXISTS(SELECT 1 FROM loan_openings o JOIN ledger_accounts a ON a.id=NEW.interest_receivable_account_id AND a.currency=o.currency JOIN ledger_accounts b ON b.id=NEW.clearing_account_id AND b.currency=o.currency WHERE o.loan_id=NEW.loan_id AND o.journal_id=NEW.opening_journal_id AND o.clearing_account_id=NEW.clearing_account_id AND o.receivable_account_id<>NEW.interest_receivable_account_id AND NEW.interest_receivable_account_id<>NEW.clearing_account_id AND (o.principal_minor=0 OR EXISTS(SELECT 1 FROM journal_entries j WHERE j.id=o.journal_id AND j.status='posted' AND NOT EXISTS(SELECT 1 FROM journal_entries r WHERE r.reverses_entry_id=j.id AND r.status='posted')))) THEN RAISE(ABORT,'opening state changed, unauthorized or invalid accounts') END;
END;
CREATE TRIGGER billing_opening_state_immutable BEFORE UPDATE ON loan_billing_opening_states BEGIN SELECT RAISE(ABORT,'opening state immutable'); END;
CREATE TRIGGER billing_opening_state_delete BEFORE DELETE ON loan_billing_opening_states WHEN NOT EXISTS(SELECT 1 FROM loan_billing_opening_state_corrections c WHERE c.loan_id=OLD.loan_id AND c.opening_request_key=OLD.request_key AND c.status='final') BEGIN SELECT RAISE(ABORT,'opening state requires reviewed correction'); END;
CREATE TRIGGER billing_opening_interest_post BEFORE UPDATE OF status ON journal_entries WHEN NEW.status='posted' AND NEW.source_type='loan-billing-opening-interest' BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM loan_billing_opening_states s JOIN loan_openings o ON o.loan_id=s.loan_id WHERE s.interest_journal_id=NEW.id AND NEW.source_id=NEW.id AND NEW.currency=o.currency AND NEW.effective_date=o.opening_date AND NEW.created_by=s.created_by AND (SELECT count(*) FROM journal_lines WHERE entry_id=NEW.id)=2 AND EXISTS(SELECT 1 FROM journal_lines WHERE entry_id=NEW.id AND account_id=s.interest_receivable_account_id AND side='debit' AND amount_minor=s.interest_due_minor) AND EXISTS(SELECT 1 FROM journal_lines WHERE entry_id=NEW.id AND account_id=s.clearing_account_id AND side='credit' AND amount_minor=s.interest_due_minor)) THEN RAISE(ABORT,'opening interest journal mismatch') END;
END;
CREATE TRIGGER billing_opening_state_correction_insert BEFORE INSERT ON loan_billing_opening_state_corrections BEGIN
 SELECT CASE WHEN NEW.status<>'pending' OR NEW.period_open_confirmed<>1 OR NOT EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.created_by AND role='admin') OR EXISTS(SELECT 1 FROM loan_billing_configs WHERE loan_id=NEW.loan_id) OR NOT EXISTS(SELECT 1 FROM loan_billing_opening_states s WHERE s.loan_id=NEW.loan_id AND s.request_key=NEW.opening_request_key AND ((s.interest_journal_id IS NULL AND NEW.reversal_journal_id IS NULL) OR (s.interest_journal_id IS NOT NULL AND NEW.reversal_journal_id IS NOT NULL))) THEN RAISE(ABORT,'opening state correction unavailable') END;
END;
CREATE TRIGGER billing_opening_state_correction_update BEFORE UPDATE ON loan_billing_opening_state_corrections BEGIN
 SELECT CASE WHEN OLD.status<>'pending' OR NEW.status<>'final' OR NEW.id IS NOT OLD.id OR NEW.loan_id IS NOT OLD.loan_id OR NEW.opening_request_key IS NOT OLD.opening_request_key OR NEW.original_details IS NOT OLD.original_details OR NEW.reversal_journal_id IS NOT OLD.reversal_journal_id OR NEW.reason IS NOT OLD.reason OR NEW.request_key IS NOT OLD.request_key OR NEW.period_open_confirmed IS NOT OLD.period_open_confirmed OR NEW.created_by IS NOT OLD.created_by OR NEW.created_at IS NOT OLD.created_at OR NOT EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.created_by AND role='admin') OR (NEW.reversal_journal_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM loan_billing_opening_states s JOIN loan_openings o ON o.loan_id=s.loan_id JOIN journal_entries j ON j.id=NEW.reversal_journal_id WHERE s.loan_id=NEW.loan_id AND j.status='posted' AND j.reverses_entry_id=s.interest_journal_id AND j.effective_date=o.opening_date AND j.created_by=NEW.created_by)) THEN RAISE(ABORT,'opening state correction incomplete') END;
END;
CREATE TRIGGER billing_opening_state_correction_no_delete BEFORE DELETE ON loan_billing_opening_state_corrections BEGIN SELECT RAISE(ABORT,'opening state correction immutable'); END;
CREATE TRIGGER billing_opening_interest_reverse BEFORE UPDATE OF status ON journal_entries WHEN NEW.status='posted' AND EXISTS(SELECT 1 FROM loan_billing_opening_states WHERE interest_journal_id=NEW.reverses_entry_id) BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM loan_billing_opening_state_corrections c JOIN loan_billing_opening_states s ON s.loan_id=c.loan_id WHERE c.status='pending' AND c.created_by=NEW.created_by AND c.reversal_journal_id=NEW.id AND s.interest_journal_id=NEW.reverses_entry_id AND NEW.source_type='loan-billing-opening-interest-reversal' AND NEW.source_id=c.id) THEN RAISE(ABORT,'opening state correction required') END;
END;
CREATE TRIGGER billing_opening_principal_reverse BEFORE INSERT ON loan_opening_corrections WHEN EXISTS(SELECT 1 FROM loan_billing_opening_states WHERE loan_id=NEW.loan_id) BEGIN SELECT RAISE(ABORT,'correct billing opening state first'); END;
DROP TRIGGER billing_config_insert;
DROP TRIGGER billing_event_validate;
CREATE TRIGGER billing_config_insert BEFORE INSERT ON loan_billing_configs BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM loan_billing_config_cancellations WHERE config_request_key=NEW.request_key) THEN RAISE(ABORT,'cancelled configuration key cannot be reused') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.created_by AND role='admin') OR NOT EXISTS(SELECT 1 FROM loans l WHERE l.id=NEW.loan_id AND l.principal_minor=NEW.principal_minor AND l.currency=NEW.currency AND l.disbursement_date=NEW.disbursement_date AND l.terms=NEW.reviewed_terms AND NOT EXISTS(SELECT 1 FROM loan_source_voids v WHERE v.source_kind='loan' AND v.source_id=l.id)) OR EXISTS(SELECT 1 FROM loan_repayments r JOIN journal_entries j ON j.source_type='loan-repayment' AND j.source_id=r.id WHERE r.loan_id=NEW.loan_id) OR EXISTS(SELECT 1 FROM loan_term_changes t WHERE t.loan_id=NEW.loan_id AND NOT EXISTS(SELECT 1 FROM loan_term_change_voids v WHERE v.term_change_id=t.id)) THEN RAISE(ABORT,'billing setup changed, unauthorized, has term amendments, or prior repayment journal exists') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM journal_entries j WHERE j.source_type='loan-disbursement' AND j.source_id=NEW.loan_id AND j.status='posted' AND NOT EXISTS(SELECT 1 FROM journal_entries x WHERE x.reverses_entry_id=j.id AND x.status='posted')) AND NOT EXISTS(SELECT 1 FROM loan_billing_opening_states o JOIN loan_openings l ON l.loan_id=o.loan_id AND l.journal_id=o.opening_journal_id WHERE (l.principal_minor=0 OR EXISTS(SELECT 1 FROM journal_entries j WHERE j.id=l.journal_id AND j.status='posted')) AND o.loan_id=NEW.loan_id AND o.rate_basis_points=NEW.rate_basis_points AND o.period_days=NEW.period_days AND (o.interest_journal_id IS NULL OR EXISTS(SELECT 1 FROM journal_entries k WHERE k.id=o.interest_journal_id AND k.status='posted'))) THEN RAISE(ABORT,'a posted unreversed loan disbursement is required') END;
END;
CREATE TRIGGER billing_event_validate BEFORE INSERT ON loan_billing_events BEGIN
 SELECT CASE WHEN NEW.event_date>date('now') THEN RAISE(ABORT,'cannot finalize future billing') END;
 SELECT CASE WHEN NEW.repayment_id IS NOT NULL AND EXISTS(SELECT 1 FROM loan_billing_events e WHERE e.repayment_id=NEW.repayment_id AND NOT EXISTS(SELECT 1 FROM loan_billing_event_voids v WHERE v.event_id=e.id AND v.status='final')) THEN RAISE(ABORT,'repayment already allocated') END;
 SELECT CASE WHEN NEW.event_date<(SELECT disbursement_date FROM loan_billing_configs WHERE loan_id=NEW.loan_id) THEN RAISE(ABORT,'billing date precedes disbursement') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.created_by AND role='admin') OR NOT EXISTS(SELECT 1 FROM loan_billing_revisions WHERE loan_id=NEW.loan_id AND revision=NEW.expected_revision) THEN RAISE(ABORT,'billing review stale or unauthorized') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM loan_billing_configs c JOIN loans l ON l.id=c.loan_id WHERE c.loan_id=NEW.loan_id AND c.request_key=NEW.config_request_key AND l.principal_minor=c.principal_minor AND l.currency=c.currency AND l.disbursement_date=c.disbursement_date AND NOT EXISTS(SELECT 1 FROM loan_source_voids v WHERE v.source_kind='loan' AND v.source_id=l.id)) THEN RAISE(ABORT,'billing loan changed') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM journal_entries j JOIN journal_lines l ON l.entry_id=j.id AND l.side='debit' WHERE j.source_type='loan-disbursement' AND j.source_id=NEW.loan_id AND j.status='posted' AND l.account_id=NEW.principal_account_id AND NOT EXISTS(SELECT 1 FROM journal_entries x WHERE x.reverses_entry_id=j.id AND x.status='posted')) AND NOT EXISTS(SELECT 1 FROM loan_billing_opening_states o JOIN loan_openings l ON l.loan_id=o.loan_id AND l.journal_id=o.opening_journal_id WHERE o.loan_id=NEW.loan_id AND l.receivable_account_id=NEW.principal_account_id AND o.interest_receivable_account_id=NEW.receivable_account_id AND NEW.event_date>=l.opening_date) THEN RAISE(ABORT,'principal account must match posted disbursement') END;
 SELECT CASE WHEN NEW.principal_account_id=NEW.receivable_account_id OR NEW.principal_account_id=NEW.income_account_id OR NEW.receivable_account_id=NEW.income_account_id OR (NEW.cash_account_id IS NOT NULL AND NEW.cash_account_id IN (NEW.principal_account_id,NEW.receivable_account_id,NEW.income_account_id)) OR (NEW.liability_account_id IS NOT NULL AND NEW.liability_account_id IN (NEW.principal_account_id,NEW.receivable_account_id,NEW.income_account_id,NEW.cash_account_id)) THEN RAISE(ABORT,'billing accounts must be distinct') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM ledger_accounts a JOIN loan_billing_configs c ON c.loan_id=NEW.loan_id WHERE a.id=NEW.principal_account_id AND a.currency=c.currency) OR NOT EXISTS(SELECT 1 FROM ledger_accounts a JOIN loan_billing_configs c ON c.loan_id=NEW.loan_id WHERE a.id=NEW.receivable_account_id AND a.currency=c.currency) OR NOT EXISTS(SELECT 1 FROM ledger_accounts a JOIN loan_billing_configs c ON c.loan_id=NEW.loan_id WHERE a.id=NEW.income_account_id AND a.currency=c.currency) OR (NEW.cash_account_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM ledger_accounts a JOIN loan_billing_configs c ON c.loan_id=NEW.loan_id WHERE a.id=NEW.cash_account_id AND a.currency=c.currency)) OR (NEW.liability_account_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM ledger_accounts a JOIN loan_billing_configs c ON c.loan_id=NEW.loan_id WHERE a.id=NEW.liability_account_id AND a.currency=c.currency)) THEN RAISE(ABORT,'billing account missing or currency mismatch') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM loan_billing_events e WHERE e.loan_id=NEW.loan_id AND NOT EXISTS(SELECT 1 FROM loan_billing_event_voids v WHERE v.event_id=e.id AND v.status='final') AND (e.principal_account_id<>NEW.principal_account_id OR e.receivable_account_id<>NEW.receivable_account_id OR e.income_account_id<>NEW.income_account_id)) THEN RAISE(ABORT,'billing accounts cannot change between events') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM loan_billing_events e WHERE e.loan_id=NEW.loan_id AND NOT EXISTS(SELECT 1 FROM loan_billing_event_voids v WHERE v.event_id=e.id AND v.status='final') AND (e.event_date>NEW.event_date OR (e.event_date=NEW.event_date AND (NEW.repayment_id IS NULL OR e.repayment_id IS NULL OR e.repayment_id>=NEW.repayment_id)))) THEN RAISE(ABORT,'billing must be finalized chronologically') END;
 SELECT CASE WHEN NEW.total_interest_minor<>NEW.accrued_minor+COALESCE((SELECT e.total_interest_minor FROM loan_billing_events e WHERE e.loan_id=NEW.loan_id AND NOT EXISTS(SELECT 1 FROM loan_billing_event_voids v WHERE v.event_id=e.id AND v.status='final') ORDER BY e.rowid DESC LIMIT 1),(SELECT recognized_interest_minor FROM loan_billing_opening_states WHERE loan_id=NEW.loan_id),0) THEN RAISE(ABORT,'billing accrual total changed') END;
 SELECT CASE WHEN NEW.repayment_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM loan_repayments r WHERE r.id=NEW.repayment_id AND r.loan_id=NEW.loan_id AND r.payment_date=NEW.event_date AND r.amount_minor=NEW.interest_minor+NEW.principal_minor+NEW.unapplied_minor AND NOT EXISTS(SELECT 1 FROM loan_source_voids v WHERE v.source_kind='repayment' AND v.source_id=r.id) AND NOT EXISTS(SELECT 1 FROM journal_entries j WHERE j.source_type='loan-repayment' AND j.source_id=r.id)) THEN RAISE(ABORT,'repayment changed or already posted') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM loan_repayments r WHERE r.loan_id=NEW.loan_id AND NOT EXISTS(SELECT 1 FROM loan_source_voids v WHERE v.source_kind='repayment' AND v.source_id=r.id) AND NOT EXISTS(SELECT 1 FROM loan_billing_events e WHERE e.repayment_id=r.id AND NOT EXISTS(SELECT 1 FROM loan_billing_event_voids v WHERE v.event_id=e.id AND v.status='final')) AND (r.payment_date<NEW.event_date OR (r.payment_date=NEW.event_date AND (NEW.repayment_id IS NULL OR r.id<NEW.repayment_id)))) THEN RAISE(ABORT,'earlier repayment must be finalized first') END;
END;
